import{_ as e,o as n,c as s,a2 as i}from"./chunks/framework.EUByU7Iq.js";const c=JSON.parse('{"title":"第五章 国家所有权和集体所有权、私人所有权","description":"","frontmatter":{"title":"第五章 国家所有权和集体所有权、私人所有权","date":"2021-02-16T00:00:00.000Z","categories":["法律","民法典"],"tags":["法律","民法典"]},"headers":[],"relativePath":"blogs/CC/dierfenbian：suoyouquan（diwuzhang：guojiasuoyouquanhejitisuoyouquan、sirensuoyouquan）.md","filePath":"blogs/CC/第二分编：所有权（第五章：国家所有权和集体所有权、私人所有权）.md"}'),r={name:"blogs/CC/dierfenbian：suoyouquan（diwuzhang：guojiasuoyouquanhejitisuoyouquan、sirensuoyouquan）.md"};function l(t,a,o,p,h,d){return n(),s("div",null,[...a[0]||(a[0]=[i(`<h3 id="第二百四十六条" tabindex="-1">第二百四十六条 <a class="header-anchor" href="#第二百四十六条" aria-label="Permalink to &quot;第二百四十六条&quot;">​</a></h3><p>法律规定属于国家所有的财产，属于国家所有即全民所有。 国有财产由国务院代表国家行使所有权。法律另有规定的，依照其规定。</p><h3 id="第二百四十七条" tabindex="-1">第二百四十七条 <a class="header-anchor" href="#第二百四十七条" aria-label="Permalink to &quot;第二百四十七条&quot;">​</a></h3><p>矿藏、水流、海域属于国家所有。</p><h3 id="第二百四十八条" tabindex="-1">第二百四十八条 <a class="header-anchor" href="#第二百四十八条" aria-label="Permalink to &quot;第二百四十八条&quot;">​</a></h3><p>无居民海岛属于国家所有，国务院代表国家行使无居民海岛所有权。</p><h3 id="第二百四十九条" tabindex="-1">第二百四十九条 <a class="header-anchor" href="#第二百四十九条" aria-label="Permalink to &quot;第二百四十九条&quot;">​</a></h3><p>城市的土地，属于国家所有。法律规定属于国家所有的农村和城市郊区的土地，属于国家所有。</p><h3 id="第二百五十条" tabindex="-1">第二百五十条 <a class="header-anchor" href="#第二百五十条" aria-label="Permalink to &quot;第二百五十条&quot;">​</a></h3><p>森林、山岭、草原、荒地、滩涂等自然资源，属于国家所有，但是法律规定属于集体所有的除外。</p><h3 id="第二百五十一条" tabindex="-1">第二百五十一条 <a class="header-anchor" href="#第二百五十一条" aria-label="Permalink to &quot;第二百五十一条&quot;">​</a></h3><p>法律规定属于国家所有的野生动植物资源，属于国家所有。</p><h3 id="第二百五十二条" tabindex="-1">第二百五十二条 <a class="header-anchor" href="#第二百五十二条" aria-label="Permalink to &quot;第二百五十二条&quot;">​</a></h3><p>无线电频谱资源属于国家所有。</p><h3 id="第二百五十三条" tabindex="-1">第二百五十三条 <a class="header-anchor" href="#第二百五十三条" aria-label="Permalink to &quot;第二百五十三条&quot;">​</a></h3><p>法律规定属于国家所有的文物，属于国家所有。</p><h3 id="第二百五十四条" tabindex="-1">第二百五十四条 <a class="header-anchor" href="#第二百五十四条" aria-label="Permalink to &quot;第二百五十四条&quot;">​</a></h3><p>国防资产属于国家所有。 铁路、公路、电力设施、电信设施和油气管道等基础设施，依照法律规定为国家所有的，属于国家所有。</p><h3 id="第二百五十五条" tabindex="-1">第二百五十五条 <a class="header-anchor" href="#第二百五十五条" aria-label="Permalink to &quot;第二百五十五条&quot;">​</a></h3><p>国家机关对其直接支配的不动产和动产，享有占有、使用以及依照法律和国务院的有关规定处分的权利。</p><h3 id="第二百五十六条" tabindex="-1">第二百五十六条 <a class="header-anchor" href="#第二百五十六条" aria-label="Permalink to &quot;第二百五十六条&quot;">​</a></h3><p>国家举办的事业单位对其直接支配的不动产和动产，享有占有、使用以及依照法律和国务院的有关规定收益、处分的权利。</p><h3 id="第二百五十七条" tabindex="-1">第二百五十七条 <a class="header-anchor" href="#第二百五十七条" aria-label="Permalink to &quot;第二百五十七条&quot;">​</a></h3><p>国家出资的企业，由国务院、地方人民政府依照法律、行政法规规定分别代表国家履行出资人职责，享有出资人权益。</p><h3 id="第二百五十八条" tabindex="-1">第二百五十八条 <a class="header-anchor" href="#第二百五十八条" aria-label="Permalink to &quot;第二百五十八条&quot;">​</a></h3><p>国家所有的财产受法律保护，禁止任何组织或者个人侵占、哄抢、私分、截留、破坏。</p><h3 id="第二百五十九条" tabindex="-1">第二百五十九条 <a class="header-anchor" href="#第二百五十九条" aria-label="Permalink to &quot;第二百五十九条&quot;">​</a></h3><p>履行国有财产管理、监督职责的机构及其工作人员，应当依法加强对国有财产的管理、监督，促进国有财产保值增值，防止国有财产损失；滥用职权，玩忽职守，造成国有财产损失的，应当依法承担法律责任。 违反国有财产管理规定，在企业改制、合并分立、关联交易等过程中，低价转让、合谋私分、擅自担保或者以其他方式造成国有财产损失的，应当依法承担法律责任。</p><h3 id="第二百六十条" tabindex="-1">第二百六十条 <a class="header-anchor" href="#第二百六十条" aria-label="Permalink to &quot;第二百六十条&quot;">​</a></h3><p>集体所有的不动产和动产包括：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>（一）法律规定属于集体所有的土地和森林、山岭、草原、荒地、滩涂；</span></span>
<span class="line"><span>（二）集体所有的建筑物、生产设施、农田水利设施；</span></span>
<span class="line"><span>（三）集体所有的教育、科学、文化、卫生、体育等设施；</span></span>
<span class="line"><span>（四）集体所有的其他不动产和动产。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><h3 id="第二百六十一条" tabindex="-1">第二百六十一条 <a class="header-anchor" href="#第二百六十一条" aria-label="Permalink to &quot;第二百六十一条&quot;">​</a></h3><p>农民集体所有的不动产和动产，属于本集体成员集体所有。 下列事项应当依照法定程序经本集体成员决定：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>（一）土地承包方案以及将土地发包给本集体以外的组织或者个人承包；</span></span>
<span class="line"><span>（二）个别土地承包经营权人之间承包地的调整；</span></span>
<span class="line"><span>（三）土地补偿费等费用的使用、分配办法；</span></span>
<span class="line"><span>（四）集体出资的企业的所有权变动等事项；</span></span>
<span class="line"><span>（五）法律规定的其他事项。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><h3 id="第二百六十二条" tabindex="-1">第二百六十二条 <a class="header-anchor" href="#第二百六十二条" aria-label="Permalink to &quot;第二百六十二条&quot;">​</a></h3><p>对于集体所有的土地和森林、山岭、草原、荒地、滩涂等，依照下列规定行使所有权：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>（一）属于村农民集体所有的，由村集体经济组织或者村民委员会依法代表集体行使所有权；</span></span>
<span class="line"><span>（二）分别属于村内两个以上农民集体所有的，由村内各该集体经济组织或者村民小组依法代表集体行使所有权；</span></span>
<span class="line"><span>（三）属于乡镇农民集体所有的，由乡镇集体经济组织代表集体行使所有权。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><h3 id="第二百六十三条" tabindex="-1">第二百六十三条 <a class="header-anchor" href="#第二百六十三条" aria-label="Permalink to &quot;第二百六十三条&quot;">​</a></h3><p>城镇集体所有的不动产和动产，依照法律、行政法规的规定由本集体享有占有、使用、收益和处分的权利。</p><h3 id="第二百六十四条" tabindex="-1">第二百六十四条 <a class="header-anchor" href="#第二百六十四条" aria-label="Permalink to &quot;第二百六十四条&quot;">​</a></h3><p>农村集体经济组织或者村民委员会、村民小组应当依照法律、行政法规以及章程、村规民约向本集体成员公布集体财产的状况。集体成员有权查阅、复制相关资料。</p><h3 id="第二百六十五条" tabindex="-1">第二百六十五条 <a class="header-anchor" href="#第二百六十五条" aria-label="Permalink to &quot;第二百六十五条&quot;">​</a></h3><p>集体所有的财产受法律保护，禁止任何组织或者个人侵占、哄抢、私分、破坏。 农村集体经济组织、村民委员会或者其负责人作出的决定侵害集体成员合法权益的，受侵害的集体成员可以请求人民法院予以撤销。</p><h3 id="第二百六十六条" tabindex="-1">第二百六十六条 <a class="header-anchor" href="#第二百六十六条" aria-label="Permalink to &quot;第二百六十六条&quot;">​</a></h3><p>私人对其合法的收入、房屋、生活用品、生产工具、原材料等不动产和动产享有所有权。</p><h3 id="第二百六十七条" tabindex="-1">第二百六十七条 <a class="header-anchor" href="#第二百六十七条" aria-label="Permalink to &quot;第二百六十七条&quot;">​</a></h3><p>私人的合法财产受法律保护，禁止任何组织或者个人侵占、哄抢、破坏。</p><h3 id="第二百六十八条" tabindex="-1">第二百六十八条 <a class="header-anchor" href="#第二百六十八条" aria-label="Permalink to &quot;第二百六十八条&quot;">​</a></h3><p>国家、集体和私人依法可以出资设立有限责任公司、股份有限公司或者其他企业。国家、集体和私人所有的不动产或者动产投到企业的，由出资人按照约定或者出资比例享有资产收益、重大决策以及选择经营管理者等权利并履行义务。</p><h3 id="第二百六十九条" tabindex="-1">第二百六十九条 <a class="header-anchor" href="#第二百六十九条" aria-label="Permalink to &quot;第二百六十九条&quot;">​</a></h3><p>营利法人对其不动产和动产依照法律、行政法规以及章程享有占有、使用、收益和处分的权利。 营利法人以外的法人，对其不动产和动产的权利，适用有关法律、行政法规以及章程的规定。</p><h3 id="第二百七十条" tabindex="-1">第二百七十条 <a class="header-anchor" href="#第二百七十条" aria-label="Permalink to &quot;第二百七十条&quot;">​</a></h3><p>社会团体法人、捐助法人依法所有的不动产和动产，受法律保护。</p>`,53)])])}const b=e(r,[["render",l]]);export{c as __pageData,b as default};
